3: // Phase 6 - the measured accessibility tasks (T136, T137, T140).
4: //
5: // All three were measured with `scripts/visual/probe-metrics.cjs` against the
6: // BUILT renderer, offscreen, over 8 routes:
7: //
8: //   T137  contrast, 3 themes: 131 distinct failures -> 0. Orbital and
9: //         High-contrast went 15 -> 0 each; Solar Light 101 -> 0.
10: //   T136  announcement order: every route now has exactly one h1 and no
11: //         skipped heading level. Workspace previously announced a single
12: //         alert and no structure at all.
13: //   T140  keyboard reach at 800x680, the production minimum: 0 unreachable
14: //         controls on every route, and History no longer overflows a
15: //         container that cannot be scrolled to reach it.
16: //
17: // These tests lock the CAUSES so the numbers cannot quietly come back.
18: 
19: const assert = require("node:assert/strict");
20: const { test } = require("node:test");
21: const fs = require("node:fs");
22: const path = require("node:path");
23: 
24: const rendererRoot = path.join(__dirname, "..", "src", "groundstation", "renderer");
25: const read = (...parts) => fs.readFileSync(path.join(rendererRoot, ...parts), "utf8");
26: 
27: test("T137 - no live rule paints a status role with a hand-written palette entry", () => {
28:   // These six literals WERE the dark theme, written out by hand. Each is a role
29:   // that a theme has to be able to move; none of them followed one.
30:   const banned = ["#77e1b3", "#9bcaff", "#7faedc", "#efaaa4", "#ef9189", "#8795a9", "#3ecf8e"];
31:   const offenders = [];
32:   const walk = dir => {
33:     for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
34:       const full = path.join(dir, entry.name);
35:       if (entry.isDirectory()) { walk(full); continue; }
36:       if (!entry.name.endsWith(".css")) continue;
37:       const source = fs.readFileSync(full, "utf8");
38:       // A palette file IS the palette, and so is the terminal-surface block:
39:       // the terminal keeps its own ink because it keeps its own theme. What
40:       // this forbids is a COMPONENT rule naming a colour a theme cannot move.
41:       if (entry.name === "tokens-bridge.css" || entry.name === "tokens.css") continue;
42:       const withoutTerminalPalette = source.replace(/--mc-term-[a-z]+: #[0-9a-f]{3,8};/gi, "");
43:       for (const literal of banned) {
44:         if (new RegExp(literal, "i").test(withoutTerminalPalette)) offenders.push(`${entry.name}: ${literal}`);
45:       }
46:     }
47:   };
48:   walk(rendererRoot);
49:   assert.deepEqual(offenders, [], `status roles must read a token, not a palette entry:\n${offenders.join("\n")}`);
50: });
51: 
52: test("T137 - the Solar palette carries the measured values, not the pretty ones", () => {
53:   const tokens = read("redesign", "tokens-bridge.css");
54:   const solar = tokens.slice(tokens.indexOf(".theme-solar {"), tokens.indexOf(".theme-contrast {"));
55: 
56:   // Each was solved as the lightest tone still clearing 4.5:1 against every
57:   // Solar surface it lands on. `--mc-text-dim` at #626c7a measured 4.45 -
58:   // readable-looking, and failing on 45 elements.
59:   assert.match(solar, /--mc-text-dim: #59626f;/);
60:   assert.match(solar, /--mc-ok: #026733;/);
61:   assert.match(solar, /--mc-warning: #8c5400;/);
62:   assert.match(solar, /--mc-danger: #b52833;/);
63:   assert.match(solar, /--mc-accent: #2161c2;/);
64:   assert.match(solar, /measured values, not chosen ones/);
65: });
66: 
67: test("T137 - the frozen accent primitives follow the theme", () => {
68:   const cockpit = read("redesign", "cockpit.css");
69:   // `--red: var(--accent-danger)` made this the winning alias block, and
70:   // `--accent-danger` pointed at a fixed dark primitive - so History's "why it
71:   // needs review" heading stayed dark-theme red on a white card at 2.63:1.
72:   assert.match(cockpit, /--accent-warning: var\(--mc-warning\);/);
73:   assert.match(cockpit, /--accent-danger: var\(--mc-danger\);/);
74:   assert.match(cockpit, /--accent-attention: var\(--mc-warning\);/);
75:   assert.doesNotMatch(cockpit, /--accent-danger: var\(--red-300\);/);
76: });
77: 
78: test("T137 - the terminal surface has its own status ink", () => {
79:   const workspace = read("redesign", "workspace.css");
80:   // The pane stays dark whatever the page theme is, so the page's status inks
81:   // are wrong over it: Solar's warning is a dark brown and it landed on a
82:   // near-black pane at 2.32:1.
83:   assert.match(workspace, /--mc-term-ok:/);
84:   assert.match(workspace, /--mc-term-warning:/);
85:   assert.match(workspace, /--mc-term-danger:/);
86:   assert.match(workspace, /\.terminal-pane__activity\.is-attention \{ color: var\(--mc-term-warning\)/);
87:   assert.match(workspace, /\.terminal-pane__activity\.is-failed \{ color: var\(--mc-term-danger\)/);
88:   assert.match(workspace, /\.terminal-pane \.terminal-warning \{/);
89: });
90: 
91: test("T137 - the nav's current destination and the attention badge are readable in every theme", () => {
92:   const base = read("redesign", "base.css");
93:   // `color: #fff` on `--mc-accent-soft`, which is a LIGHT wash in Solar: the
94:   // destination a reader most needs measured 1.38:1 against its own background.
95:   assert.match(base, /\.top-navigation button\.is-current \{\s*\n\s*color: var\(--mc-text\) !important;/);
96:   assert.doesNotMatch(base, /\.top-navigation button\.is-current \{[\s\S]{0,120}color: #fff/);
97:   // White on the danger fill measured 3.03:1 for 9.5px bold text.
98:   assert.match(base, /color: var\(--mc-text-ink\) !important;\s*\n\s*background: var\(--mc-danger\) !important;/);
99: });
100: 
101: test("T136 - `.sr-only` is defined, and clips rather than hiding", () => {
102:   const base = read("redesign", "base.css");
103:   const rule = base.slice(base.indexOf(".sr-only,"), base.indexOf(".sr-only:focus-visible"));
104:   assert.match(rule, /clip-path: inset\(50%\)/);
105:   // display:none and visibility:hidden take the node out of the accessibility
106:   // tree too, which is the opposite of what an sr-only label needs.
107:   assert.doesNotMatch(rule, /display: none|visibility: hidden/);
108:   assert.match(base, /\.sr-only:focus-visible/, "a focusable sr-only control must come back on focus");
109: 
110:   // It was used in three places and defined in none, so those labels rendered
111:   // as visible stray text.
112:   assert.match(read("LoadingSkeleton.jsx"), /className="sr-only"/);
113:   assert.match(read("ProjectsView.jsx"), /className="sr-only"/);
114: });
115: 
116: test("T136 - every route names itself with exactly one h1, and Workspace has landmarks", () => {
117:   const app = read("App.jsx");
118:   for (const heading of ["Groundstation", "Needs You", "History", "Terminal Workspace"]) {
119:     assert.ok(app.includes(`<h1 className="sr-only">${heading}</h1>`), `${heading} has no page heading`);
120:   }
121:   // The Workspace announced one alert and nothing else; the folder rail is a
122:   // navigation region, not an anonymous div.
123:   assert.match(app, /<nav className="worker-folders" aria-label="Worker folders">/);
124: 
125:   // Agents had two h1 elements: the page and the selected agent.
126:   const agents = read("AgentWorkspace.jsx");
127:   assert.match(agents, /<h1>Supervised agents<\/h1>/);
128:   assert.match(agents, /<h2>\{agentName\(selected\)\}<\/h2>/);
129:   assert.equal((agents.match(/<h1>/g) || []).length, 1);
130:   // The rules that styled it follow the tag change.
131:   assert.match(read("redesign", "cockpit.css"), /\.agent-detail-title :is\(h1, h2\)/);
132:   assert.match(read("uiFoundation.css"), /\.agent-detail-title :is\(h1, h2\)/);
133: 
134:   // Settings jumped h1 -> h3; the active group is the missing level and also
135:   // tells a reader which of the eight they are in.
136:   assert.match(app, /<h2 className="sr-only">\{SETTINGS_GROUPS\.find\(\(\[id\]\) => id === group\)\?\.\[1\] \|\| "Settings"\}<\/h2>/);
137: });
