139: test("T140 - History wraps at the production floor instead of running off the side", () => {
140:   const screens = read("redesign", "screens.css");
141:   const block = screens.slice(screens.indexOf("History at the production floor (T140)"));
142:   assert.ok(block.length > 0, "the fix must record what was measured");
143:   assert.match(block, /scrollWidth 831 in a 542px track/);
144:   assert.match(block, /\.history-controls \{[\s\S]{0,120}flex-wrap: wrap;/);
145:   assert.match(block, /\.history-actors \{ flex-wrap: wrap;/);
146:   assert.match(block, /\.history-export \{ flex: 1 0 100%; \}/);
147:   // The two-column splits collapse rather than forcing the page wider.
148:   assert.match(block, /@media \(max-width: 900px\)/);
149:   assert.match(block, /\.memory-briefing \{ grid-template-columns: minmax\(0, 1fr\); \}/);
150: });
